import{_ as s,o as e,c as a,a2 as t}from"./chunks/framework.76ZGnlPi.js";const c=JSON.parse('{"title":"Search & Booking Limits Guide","description":"","frontmatter":{},"headers":[],"relativePath":"admin/search-booking-limits/index.md","filePath":"admin/search-booking-limits/index.md"}'),n={name:"admin/search-booking-limits/index.md"};function o(d,i,l,r,h,p){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="search-booking-limits-guide" tabindex="-1">Search &amp; Booking Limits Guide <a class="header-anchor" href="#search-booking-limits-guide" aria-label="Permalink to &quot;Search &amp; Booking Limits Guide&quot;">​</a></h1><p>This guide explains how an admin configures the group-size and advance-booking limits that gate <strong>search</strong> and <strong>booking creation</strong> across the three products: <code>ota</code> (retail), <code>blockseat</code> (wholesale), and <code>custom</code>.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Previously the front-end hardcoded these limits (minimum 10 seated passengers for custom SILVER, 5 for GOLD; a 3-day advance rule for wholesale) and the back-end owned only part of them via environment variables. This module moves them into a small database table an admin can edit, and exposes a public read endpoint so the front-end drives its own validation from the returned numbers instead of hardcoding.</p><p>Two dimensions are configurable per product:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>minSeatedPax</code></td><td>Minimum seated passengers (<strong>adults + children</strong>; infants sit on a lap and are never counted). <code>null</code> = no floor.</td></tr><tr><td><code>minAdvanceDays</code></td><td>Departure must be at least <code>n × 24</code> hours ahead (midnight-UTC anchor). <code>null</code> / <code>0</code> = no advance rule. <code>3</code> = 72 hours.</td></tr></tbody></table><h3 id="the-grid-4-cells" tabindex="-1">The grid (4 cells) <a class="header-anchor" href="#the-grid-4-cells" aria-label="Permalink to &quot;The grid (4 cells)&quot;">​</a></h3><p>Tier only splits <code>custom</code> (GOLD vs everyone-else). <code>ota</code> and <code>blockseat</code> are tier-flat.</p><table tabindex="0"><thead><tr><th>product</th><th>tier</th><th>default <code>minSeatedPax</code></th><th>default <code>minAdvanceDays</code></th></tr></thead><tbody><tr><td>OTA</td><td>(base)</td><td>1</td><td>0</td></tr><tr><td>BLOCKSEAT</td><td>(base)</td><td>11</td><td>3</td></tr><tr><td>CUSTOM</td><td>(base)</td><td>10</td><td>0</td></tr><tr><td>CUSTOM</td><td>GOLD</td><td>5</td><td>0</td></tr></tbody></table><blockquote><p>The table is <strong>empty on deploy</strong>, so these defaults (seeded from the existing env values) fire and behaviour is identical to before until an admin saves a row.</p></blockquote><h3 id="search-vs-booking-creation-split" tabindex="-1">Search vs booking-creation split <a class="header-anchor" href="#search-vs-booking-creation-split" aria-label="Permalink to &quot;Search vs booking-creation split&quot;">​</a></h3><p>A limit violation behaves differently depending on where it is hit:</p><ul><li><strong>Search endpoints</strong> return an <strong>empty result</strong> (no error) when a limit is violated — the same way OTA&#39;s existing 72-hour group rule already behaves.</li><li><strong>Booking creation and price-calculation</strong> throw a <code>400 Bad Request</code>.</li></ul><blockquote><p><strong>Behaviour change to flag:</strong> wholesale (<code>blockseat</code>) search previously threw a <code>400</code> for fewer than 11 passengers. It now returns an empty result at search and only throws at calculate / booking-creation. Wholesale search also gains a real server-side <code>&lt;72h</code> advance gate (previously only the supplier rejected <code>&lt;72h</code>). Custom search now enforces the floor for <strong>logged-in</strong> callers (empty results below the floor); guests can still browse.</p></blockquote><hr><h2 id="fallback-order" tabindex="-1">Fallback order <a class="header-anchor" href="#fallback-order" aria-label="Permalink to &quot;Fallback order&quot;">​</a></h2><p>For each <code>(product, tier)</code> cell the effective value is resolved as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DB row  →  environment variable  →  built-in default</span></span></code></pre></div><p>Fallback is <strong>row-level, not field-level</strong>: if a DB row exists, its values win as-is, and a <code>null</code> field means &quot;no rule&quot; (the floor is OFF). It does <strong>not</strong> re-fall-back to the env value — otherwise an admin could never turn a floor off.</p><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>All admin endpoints require a JWT with role <code>ADMIN</code> and the relevant <code>search-booking-limits:*</code> permission.</p><h3 id="get-api-v1-admin-search-booking-limits" tabindex="-1"><code>GET /api/v1/admin/search-booking-limits</code> <a class="header-anchor" href="#get-api-v1-admin-search-booking-limits" aria-label="Permalink to &quot;`GET /api/v1/admin/search-booking-limits`&quot;">​</a></h3><p>Returns the 4-cell grid (DB rows merged over defaults). Each row carries <code>isDefault: true</code> when no DB override exists.</p><h3 id="put-api-v1-admin-search-booking-limits" tabindex="-1"><code>PUT /api/v1/admin/search-booking-limits</code> <a class="header-anchor" href="#put-api-v1-admin-search-booking-limits" aria-label="Permalink to &quot;`PUT /api/v1/admin/search-booking-limits`&quot;">​</a></h3><p>Bulk-updates the grid. <strong>All rows are validated first, then upserted in one transaction</strong> — a single invalid row rejects the whole request (<code>400</code>) and nothing is half-saved.</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;limits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;product&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OTA&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,       </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minSeatedPax&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minAdvanceDays&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;product&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BLOCKSEAT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minSeatedPax&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minAdvanceDays&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;product&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CUSTOM&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,     </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minSeatedPax&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minAdvanceDays&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;product&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CUSTOM&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,     </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GOLD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minSeatedPax&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;minAdvanceDays&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Validation rules:</p><ul><li><code>product</code> must be one of <code>OTA</code>, <code>BLOCKSEAT</code>, <code>CUSTOM</code>.</li><li><code>tier</code> must be <code>&quot;GOLD&quot;</code> or <code>null</code>. A <code>GOLD</code> row is <strong>only</strong> valid for <code>CUSTOM</code>.</li><li><code>minSeatedPax</code> / <code>minAdvanceDays</code> are non-negative integers or <code>null</code>.</li><li>Setting a field to <code>null</code> clears that rule (turns the floor off).</li></ul><h3 id="get-api-v1-admin-search-booking-limits-defaults" tabindex="-1"><code>GET /api/v1/admin/search-booking-limits/defaults</code> <a class="header-anchor" href="#get-api-v1-admin-search-booking-limits-defaults" aria-label="Permalink to &quot;`GET /api/v1/admin/search-booking-limits/defaults`&quot;">​</a></h3><p>Returns the env / built-in default matrix (the values used when no DB row exists).</p><h3 id="get-api-v1-admin-search-booking-limits-history" tabindex="-1"><code>GET /api/v1/admin/search-booking-limits/history</code> <a class="header-anchor" href="#get-api-v1-admin-search-booking-limits-history" aria-label="Permalink to &quot;`GET /api/v1/admin/search-booking-limits/history`&quot;">​</a></h3><p>Returns the persisted rows with last-editor audit, paginated. The table upserts in place, so this is current state + last editor, not a per-change version trail.</p><hr><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Grants</th></tr></thead><tbody><tr><td><code>search-booking-limits:read</code></td><td>View the grid, defaults, and history.</td></tr><tr><td><code>search-booking-limits:update</code></td><td>Save (bulk-update) the grid.</td></tr><tr><td><code>search-booking-limits:*</code></td><td>Both.</td></tr></tbody></table><p>These are unassigned in the predefined roles by default — grant them to an Access Role as needed (matching how <code>mitra-pricing</code> / <code>tariff-pricing</code> are left unassigned).</p>',38)])])}const u=s(n,[["render",o]]);export{c as __pageData,u as default};
